<?php $title='Chat Pengurus | '.($settings['site_name']??'Sukamulya');$citizen_dashboard=TRUE;$this->load->view('site/header',compact('title','settings','menu','citizen_dashboard'));$last_id=0; ?>
<main class="citizen-chat-page"><div class="wrap"><section class="chat-hero"><div><span>LAYANAN WARGA</span><h1>Live Chat <b>Warga</b></h1><p>Hubungi admin atau pengurus yang sedang online secara langsung.</p></div></section><div class="citizen-chat-layout"><aside class="chat-admin-list"><header><h2>Pengurus RT</h2><span id="online-count"><?= count(array_filter($admins,function($a){return !empty($a['is_online']);})) ?> online</span></header><?php foreach($admins as $admin): ?><a class="chat-admin-row <?= (int)($conversation['assigned_admin_id']??0)===(int)$admin['id']?'active':'' ?>" href="<?= site_url('warga/chat') ?>?admin=<?= (int)$admin['id'] ?>"><span class="chat-avatar">A<i class="<?= $admin['is_online']?'online':'offline' ?>"></i></span><span><strong><?= html_escape(ucwords(str_replace('_',' ',$admin['username']))) ?></strong><small><?= html_escape(ucfirst($admin['role'])) ?> · <?= $admin['is_online']?'Online':'Offline' ?></small></span></a><?php endforeach; ?><?php if(!$admins): ?><p class="chat-empty">Belum ada akun pengurus.</p><?php endif; ?></aside><section class="chat-window"><header><span class="chat-avatar">A<i class="<?= $assigned_admin?'online':'offline' ?>"></i></span><div><strong><?= $assigned_admin?html_escape(ucwords(str_replace('_',' ',$assigned_admin['username']))):'Pengurus RT' ?></strong><small><?= $assigned_admin?html_escape(ucfirst($assigned_admin['role'])):'Pilih pengurus untuk memulai chat' ?></small></div></header><div class="chat-messages" id="chat-messages"><?php foreach($messages as $message):$last_id=max($last_id,(int)$message['id']); ?><div class="chat-bubble <?= $message['sender_type']==='citizen'?'mine':'theirs' ?>" data-id="<?= (int)$message['id'] ?>"><p><?= nl2br(html_escape($message['message'])) ?></p><time><?= date('H:i',strtotime($message['created_at'])) ?><?= $message['sender_type']==='citizen'&&$message['is_read']?' ✓✓':'' ?></time></div><?php endforeach; ?><?php if(!$messages): ?><div class="chat-empty-state" id="chat-empty"><b>💬</b><strong>Mulai percakapan</strong><p>Tulis pesan untuk admin atau pengurus RT.</p></div><?php endif; ?></div><form class="chat-compose" id="chat-form"><input type="hidden" name="admin_id" value="<?= (int)($conversation['assigned_admin_id']??0) ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><textarea name="message" rows="1" maxlength="2000" placeholder="Tulis pesan..." required></textarea><button type="submit" aria-label="Kirim pesan">➤</button></form></section></div></div></main>
<script>(function(){const box=document.getElementById('chat-messages'),form=document.getElementById('chat-form'),csrfName='<?= $this->security->get_csrf_token_name() ?>';let last=<?= (int)$last_id ?>,busy=false;function bottom(){box.scrollTop=box.scrollHeight}function bubble(m){if(document.querySelector('[data-id="'+m.id+'"]'))return;document.getElementById('chat-empty')?.remove();const d=document.createElement('div');d.className='chat-bubble '+(m.sender_type==='citizen'?'mine':'theirs');d.dataset.id=m.id;const p=document.createElement('p');p.textContent=m.message;const t=document.createElement('time');t.textContent=m.created_at.slice(11,16)+(m.sender_type==='citizen'&&Number(m.is_read)?' ✓✓':'');d.append(p,t);box.append(d);last=Math.max(last,Number(m.id));bottom()}async function poll(){if(busy)return;try{const r=await fetch('<?= site_url('warga/chat/pesan') ?>?after='+last,{headers:{'X-Requested-With':'XMLHttpRequest'}});if(!r.ok)return;const j=await r.json();j.messages.forEach(bubble);form.elements[csrfName].value=j.csrf}catch(e){}}form.addEventListener('submit',async e=>{e.preventDefault();busy=true;try{const r=await fetch('<?= site_url('warga/chat/kirim') ?>',{method:'POST',body:new FormData(form),headers:{'X-Requested-With':'XMLHttpRequest'}});if(!r.ok)throw Error();const j=await r.json();form.elements[csrfName].value=j.csrf;form.elements.message.value='';await poll()}catch(e){alert('Pesan belum berhasil dikirim. Silakan coba lagi.')}finally{busy=false;poll()}});form.elements.message.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();form.requestSubmit()}});bottom();setInterval(poll,3000)})();</script>
<script>setInterval(async()=>{try{const r=await fetch('<?= site_url('warga/chat/pesan') ?>?after=999999999',{headers:{'X-Requested-With':'XMLHttpRequest'}}),j=await r.json();j.admins.forEach(a=>{const row=[...document.querySelectorAll('.chat-admin-row')].find(x=>x.href.includes('admin='+a.id));if(!row)return;const dot=row.querySelector('.chat-avatar i'),small=row.querySelector('small');dot.className=Number(a.is_online)?'online':'offline';small.textContent=a.role.charAt(0).toUpperCase()+a.role.slice(1)+' · '+(Number(a.is_online)?'Online':'Offline')})}catch(e){}},5000)</script>
<?php $this->load->view('site/footer',compact('settings')); ?>
